(()=>{'use strict';const root=document.querySelector('.grid-operation');if(!root)return;const $=id=>document.getElementById(id),reduce=matchMedia('(prefers-reduced-motion: reduce)');let scenario='normal',step=0,playing=!reduce.matches,visible=false,elapsed=0,last=0;
// Explanatory states based on the linked Grid documentation, not a live runtime.
const receive={node:'source',state:'Received',title:'Receive the message. Acknowledge the source.',copy:'The LLP source accepts an HL7 message. Its default ACK confirms acceptance into the workflow, not delivery to the downstream system.',label:'INBOUND / SYNTHETIC HL7',payload:'Message type: ADT^A01\nPID-3: TEST000001\nPID-5: Example^Alex\nSource ACK: accepted into workflow'};
const queued={node:'queue-in',edge:0,state:'Queued',title:'Hand off through a durable queue.',copy:'Grid provisions queues for connected nodes. The message waits if the next node is stopped or slow; it is not passed through a direct function call.',label:'NODE CONNECTION',payload:'Receive ADT → durable queue → Map ADT\nOrdering: preserved along the connection\nDelivery: at-least-once\nQueue configuration: managed by Grid'};
const parse={node:'transform',edge:1,state:'Parsing',title:'Parse fields using your schema.',copy:'The transformation node extracts the HL7 message into a navigable tree. Your logic checks the message type and required patient identifier.',label:'PARSED FIELDS',payload:'Message type → ADT\nPID-3 → TEST000001\nPID-5 / family → Example\nRequired identifier → present'};
const mapped={node:'transform',state:'Mapped',title:'Apply your mapping, then push onward.',copy:'In the documented sample, the transformation copies the inbound message and uppercases the family name. A push sends the result to connected downstream nodes; scripts do not name the destination.',label:'BEFORE → AFTER',payload:'PID-5 / family\nExample → EXAMPLE\n\nOther mapped fields are preserved.\nOutput follows the workflow connections.'};
const outbound={node:'queue-out',edge:2,state:'Queued',title:'Buffer the transformed message.',copy:'The output enters the queue for the destination node. Your workflow connections determine where it goes, and a slow destination can build a visible backlog.',label:'OUTBOUND PAYLOAD / SYNTHETIC',payload:'Message type: ADT^A01\nPID-3: TEST000001\nPID-5: EXAMPLE^Alex\nNext node: Send ADT'};
const delivered={node:'destination',edge:3,state:'ACK verified',title:'Send and verify the receiver’s ACK.',copy:'With Wait for Ack enabled, Destination LLP waits for the receiver. The documented configuration checks the original message ID and type before treating the ACK as a match.',label:'DESTINATION CONFIGURATION',payload:'Wait for Ack: on\nACK verification: original ID + message type\nExample outcome: matching positive ACK\nSource ACK and receiver ACK are separate.'};
const history={node:'history',state:'Recorded',title:'Trace the journey across nodes.',copy:'Payloads, node events, script output and errors are recorded in the Log DB in the background. A correlation ID links the records across the workflow for investigation.',label:'MESSAGE HISTORY',payload:'Correlation: DEMO-JOURNEY-001\nReceive ADT → original payload\nMap ADT → transformed payload\nSend ADT → destination activity\nHistory becomes searchable asynchronously.'};
function sequence(){return [receive,queued,parse,mapped,outbound,delivered,history];}
function render(){const seq=sequence(),s=seq[step];root.classList.toggle('motion-stopped',!playing);document.querySelectorAll('[data-runtime-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.runtimeScenario===scenario)));root.querySelectorAll('[data-runtime-node]').forEach(b=>{const active=b.dataset.runtimeNode===s.node;b.classList.toggle('active',active);b.classList.toggle('issue',active&&!!s.issue);b.setAttribute('aria-pressed',String(active));b.querySelector('.runtime-state').textContent=active?s.state:'Ready';});root.querySelectorAll('.runtime-connector').forEach((e,i)=>e.classList.toggle('active',i===s.edge));root.querySelector('.runtime-history').classList.toggle('active',s.node==='history');$('runtime-label').textContent=`0${step+1} / ${scenario==='normal'?'SUCCESSFUL DELIVERY':scenario==='invalid'?'DATA ERROR':'CONNECTION RECOVERY'}`;$('runtime-title').textContent=s.title;$('runtime-copy').textContent=s.copy;$('runtime-payload-label').textContent=s.label;$('runtime-payload').textContent=s.payload;$('runtime-counter').textContent=`0${step+1} / 0${seq.length}`;$('runtime-play').textContent=playing?'Pause animation Ⅱ':'Play animation ▷';$('runtime-play').setAttribute('aria-pressed',String(!playing));}
root.querySelectorAll('[data-runtime-scenario]').forEach(b=>b.addEventListener('click',()=>{scenario=b.dataset.runtimeScenario;step=0;elapsed=0;render();}));root.querySelectorAll('[data-runtime-node]').forEach(b=>b.addEventListener('click',()=>{const n=sequence().findIndex(s=>s.node===b.dataset.runtimeNode);if(n>=0){step=n;elapsed=0;playing=false;render();}}));$('runtime-play').addEventListener('click',()=>{playing=!playing;elapsed=0;render();});function move(dir){step=(step+dir+sequence().length)%sequence().length;elapsed=0;playing=false;render();}$('runtime-back').addEventListener('click',()=>move(-1));$('runtime-next').addEventListener('click',()=>move(1));document.querySelectorAll('.global-motion').forEach(b=>b.addEventListener('click',()=>{playing=false;render();}));reduce.addEventListener('change',()=>{playing=!reduce.matches;elapsed=0;render();});if('IntersectionObserver'in window)new IntersectionObserver(es=>{visible=es[0].isIntersecting;root.classList.toggle('offscreen',!visible)},{threshold:.1}).observe(root);else visible=true;function tick(now){const dt=Math.min(now-last,100);last=now;if(playing&&visible&&!document.hidden){elapsed+=dt;if(elapsed>=5500){elapsed=0;step=(step+1)%sequence().length;render();}}requestAnimationFrame(tick);}render();requestAnimationFrame(tick);
})();
